            this.to = to;
            this.time = time;
            this.cost = cost;
        }
    }

    static class State implements Comparable<State> {
        int u;
        int cost;
        int time;

        State(int u, int cost, int time) {
            this.u = u;
            this.cost = cost;
            this.time = time;
        }

        @Override
        public int compareTo(State o) {
            return Integer.compare(this.time, o.time);
        }
    }

