        while (!pq.isEmpty()) {
            State curr = pq.poll();
            int u = curr.u;
            int c = curr.cost;
            int d = curr.time;

            if (d > dist[u][c]) {
                continue;
            }

            if (u == Y) {
                ans = d;
                break;
