public class Main {
    // Fast I/O
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0;
        private int tail = 0;

        private int read() throws IOException {
            if (head >= tail) {
                head = 0;
                tail = in.read(buffer, 0, buffer.length);
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public int nextInt() throws IOException {
            int c = read();
            while (c <= 32) {
                if (c == -1) return -1;
                c = read();
            }
            int res = 0;
            while (c > 32) {
                if (c >= '0' && c <= '9') {
                    res = res * 10 + c - '0';
                }
                c = read();
            }
            return res;
        }
    }

    // Min-heap primitiva para tipo long
    static class LongMinHeap {
        private long[] heap;
        private int size;

        public LongMinHeap(int capacity) {
            heap = new long[capacity];
            size = 0;
        }

        public void push(long val) {
            if (size == heap.length) {
                long[] newHeap = new long[heap.length << 1];
                System.arraycopy(heap, 0, newHeap, 0, heap.length);
                heap = newHeap;
            }
            int i = size++;
            while (i > 0) {
                int p = (i - 1) >>> 1;
                if (val < heap[p]) {
                    heap[i] = heap[p];
                    i = p;
                } else {
                    break;
                }
            }
            heap[i] = val;
        }

        public long poll() {
            long top = heap[0];
            long val = heap[--size];
            if (size > 0) {
                int i = 0;
                int half = size >>> 1;
                while (i < half) {
                    int left = (i << 1) + 1;
                    int right = left + 1;
                    int best = left;
                    if (right < size && heap[right] < heap[left]) {
                        best = right;
                    }
                    if (heap[best] < val) {
                        heap[i] = heap[best];
                        i = best;
                    } else {
                        break;
                    }
                }
                heap[i] = val;
            }
            return top;
        }

        public boolean isEmpty() {
            return size == 0;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner();
        int V = scanner.nextInt();
        if (V == -1) return;
        int N = scanner.nextInt();
        int M = scanner.nextInt();

        // Estrutura de lista de adjacência usando arrays planos (Forward Star)
        int[] head = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            head[i] = -1;
        }

        int maxEdges = 2 * M;
        int[] to = new int[maxEdges];
        int[] next = new int[maxEdges];
        int[] time = new int[maxEdges];
        int[] cost = new int[maxEdges];
        int edgeCount = 0;

        for (int i = 0; i < M; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            int t = scanner.nextInt();
            int p = scanner.nextInt();

            // Aresta u -> v
            to[edgeCount] = v;
            time[edgeCount] = t;
            cost[edgeCount] = p;
            next[edgeCount] = head[u];
            head[u] = edgeCount++;

            // Aresta v -> u
            to[edgeCount] = u;
            time[edgeCount] = t;
            cost[edgeCount] = p;
            next[edgeCount] = head[v];
            head[v] = edgeCount++;
        }

        int X = scanner.nextInt();
        int Y = scanner.nextInt();

        if (X == Y) {
            System.out.println(0);
            return;
        }

        // min_cost[u] guarda o menor custo com o qual u já foi expandido
        // Como o Dijkstra extrai em ordem não-decrescente de tempo,
        // só vale a pena expandir u novamente se o custo for estritamente menor.
        int[] minCost = new int[N + 1];
        for (int i = 1; i <= N; i++) {
            minCost[i] = V + 1;
        }

        LongMinHeap pq = new LongMinHeap(65536);

        // Empacotamento no long:
        // Bits 0 a 7 (8 bits): custo (0 a 200)
        // Bits 8 a 21 (14 bits): vértice u (1 a 10000)
        // Bits 22 a 62: tempo t
        long startNode = ((long) 0 << 22) | ((long) X << 8) | 0;
        pq.push(startNode);

        long ans = -1;

        while (!pq.isEmpty()) {
            long curr = pq.poll();
            int c = (int) (curr & 0xFF);
            int u = (int) ((curr >>> 8) & 0x3FFF);
            long t = curr >>> 22;

            if (c >= minCost[u]) {
                continue;
            }
            minCost[u] = c;

            if (u == Y) {
                ans = t;
                break;
            }

            for (int e = head[u]; e != -1; e = next[e]) {
                int nxt = to[e];
                int nxtCost = c + cost[e];
                if (nxtCost <= V && nxtCost < minCost[nxt]) {
                    long nxtTime = t + time[e];
                    long nextVal = (nxtTime << 22) | ((long) nxt << 8) | nxtCost;
                    pq.push(nextVal);
                }
            }
        }

        System.out.println(ans);
    }
